#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Import ListNotations. Open Scope Z_scope.

Abbreviation RSEGS := Ubsan.M.loaded_segments.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section Top.
  Context {AC : AllocCeiling} {RRND : RunRandom}.
  Context {fx : FPState} {AMB : Amb} {UL : ULim}.
  Variable MI : MallocIface SEGS L.
  Variable AINV0 : AS MI -> LibIface.mem -> Model -> Prop.
  Variables (TIGHT FRESH44 : AS MI -> Prop).
  Hypothesis DM : drv_mallocT MI AINV0 TIGHT FRESH44.
  Hypothesis LIB : lib_call_stmt SEGS L MI U1ST U1TargetConsts.LLVM_ENTRY U1TargetConsts.EMPTY_OBJ LIB_STACK lib_caps LIB_BIGCAP
                     U1TargetConsts.TD_LOCALE U1TargetConsts.GLOBAL_LOCALE.
  Hypothesis TPH : target_phase_stmt MI AINV0 TIGHT FRESH44.

  Variable sp0 : word.
  Variables a0s path : list byte.
  Variable envv : list (list byte).
  Variable tid : word.
  Variable rdraw : EntryDraw.
  Variable regs0 : bvmap 5 word.
  Variable mem0 : word -> option byte.
  Variables brk mbase : word.
  Variable fs0 : Fs.
  Variable stdin0 : InputStream.
  Variable content : list byte.
  Hypothesis Hva : valid_argv [a0s; path].
  Hypothesis Hve : valid_envp envv.
  Hypothesis Hvsp : valid_sp sp0.
  Hypothesis Htid : (0 < bv_unsigned tid < 2 ^ 22)%Z.
    (* LPS 75d69e00: [main_entry] takes the run's whole ProcInput and the mmap base
     in place of (argv, envp, uid, hwcap).  [mkProcInputC] (Amb.v:42) is the very
     input this Section's own conclusion runs -- [in_argv]/[in_envp]/[in_uid]/
     [in_hwcap] of it reduce to exactly the four the old spelling named -- so
     naming it here is the same statement, not a narrower one. *)
  Local Notation INP := (mkProcInputC [a0s; path] envv fs0 stdin0) (only parsing).
  Hypothesis ME : main_entry sp0 rdraw INP mbase tid regs0 mem0.
  (* LPS 727298f3: the launch's channel reader ([Run.valid_input]); the writes below need it *)
  Hypothesis Hrdr : a_channel_reader = true.
  Hypothesis Hbrk : valid_brk RSEGS brk.
  Hypothesis Hfile : fs_lookup fs0 path = Some content.
  Hypothesis Hpne : path <> [].
  Hypothesis Hpnd : path <> dot_path.
  Hypothesis Hplen : (length path <= 4095)%nat.
  Hypothesis FRM : frm_zero (@fp_csr fx).
  Hypothesis HAC : (alloc_ceiling = bv_unsigned sp0 - 8388608)%Z.
  Hypothesis HRR : (rr_canary = bv_unsigned (canary rdraw))%Z.
  Hypothesis HRS : (rr_secret = rr_secret_of (ed_random rdraw))%Z.

  Let SPlo : (0x7fff80000000 <= bv_unsigned sp0)%Z := proj1 Hvsp.
  Let SPhi : (bv_unsigned sp0 <= 0x800000000000)%Z := proj1 (proj2 Hvsp).
  Let SPal : (bv_unsigned sp0 mod 16 = 0)%Z := proj2 (proj2 Hvsp).
  Let L : Z := Z.of_nat (length content).
  #[local] Notation SP0 := (bv_unsigned sp0).
  #[local] Notation TID := (bv_unsigned tid).
  #[local] Notation P1 := (bv_unsigned (p1 a0s path envv rdraw)).
  #[local] Notation model0 := (U1RFront.model0 sp0 a0s path envv tid rdraw brk mbase fs0 stdin0).

  Definition KEND : TSet :=
    if (length content <? 6)%nat then t_die msg_short fs0
    else if (Z.of_nat (length content) <? 6 + hdr_cfglen content) then t_die msg_overrun fs0
    else t_target content fs0.

  Lemma body_eq : (if L <? 2 ^ 26 then KEND else t_die msg_refused fs0) = t_body content fs0.
Proof.
